CREATE TABLE IF NOT EXISTS categories (category_id BIGINT AUTO_INCREMENT PRIMARY KEY, category_name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255));
CREATE TABLE IF NOT EXISTS authors (author_id BIGINT AUTO_INCREMENT PRIMARY KEY, author_name VARCHAR(150) NOT NULL, country VARCHAR(100));
CREATE TABLE IF NOT EXISTS users (user_id BIGINT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(20) UNIQUE, membership_date DATE NOT NULL, status ENUM('ACTIVE','INACTIVE','SUSPENDED') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS books (book_id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, isbn VARCHAR(30) NOT NULL UNIQUE, category_id BIGINT NOT NULL, author_id BIGINT NOT NULL, publication_year INT, total_copies INT NOT NULL DEFAULT 1, available_copies INT NOT NULL DEFAULT 1, shelf_location VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_book_category FOREIGN KEY(category_id) REFERENCES categories(category_id), CONSTRAINT fk_book_author FOREIGN KEY(author_id) REFERENCES authors(author_id), CONSTRAINT chk_copies CHECK(total_copies >= 0 AND available_copies >= 0 AND available_copies <= total_copies));
CREATE TABLE IF NOT EXISTS transactions (transaction_id BIGINT AUTO_INCREMENT PRIMARY KEY, book_id BIGINT NOT NULL, user_id BIGINT NOT NULL, issue_date DATE NOT NULL, due_date DATE NOT NULL, return_date DATE, status ENUM('ISSUED','RETURNED','LOST','CANCELLED') NOT NULL DEFAULT 'ISSUED', fine_amount DECIMAL(10,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tx_book FOREIGN KEY(book_id) REFERENCES books(book_id), CONSTRAINT fk_tx_user FOREIGN KEY(user_id) REFERENCES users(user_id), CONSTRAINT chk_dates CHECK(due_date >= issue_date), CONSTRAINT chk_fine CHECK(fine_amount >= 0));
CREATE INDEX idx_books_title ON books(title); CREATE INDEX idx_tx_status_due ON transactions(status,due_date); CREATE INDEX idx_tx_user ON transactions(user_id);
CREATE TABLE IF NOT EXISTS audit_log (audit_id BIGINT AUTO_INCREMENT PRIMARY KEY, action_type VARCHAR(50) NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id BIGINT, details VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
